css:
.cti-rsi-bands{box-sizing:border-box;width:100%;max-width:420px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 8px;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums}
.cti-rsi-bands *{box-sizing:border-box}
.cti-rsi-bands-hd{display:flex;align-items:baseline;gap:6px;margin-bottom:6px}
.cti-rsi-bands-sym{font:700 11.5px/1 system-ui,-apple-system,"Segoe UI",sans-serif;color:#E4EBF7;letter-spacing:.02em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cti-rsi-bands-sym b{font-weight:500;font-size:8.5px;color:#5B6883;letter-spacing:.04em}
.cti-rsi-bands-tf{font-size:8px;color:#6EA8FF;border:1px solid #22304A;border-radius:3px;padding:0 4px;line-height:13px;flex-shrink:0}
.cti-rsi-bands-px{margin-left:auto;white-space:nowrap;flex-shrink:0}
.cti-rsi-bands-last{font-size:11px;color:#E4EBF7}
.cti-rsi-bands-chg{font-style:normal}
.cti-rsi-bands-par{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;padding:4px 5px;margin-bottom:6px;background:#0E1420;border:1px solid #182131;border-radius:5px}
.cti-rsi-bands-lb{font-size:8px;letter-spacing:.08em;color:#5B6883;text-transform:uppercase}
.cti-rsi-bands-step{display:inline-flex;align-items:center;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-rsi-bands-step button{width:16px;height:16px;padding:0;border:0;background:#111826;color:#93A2BC;font:700 10px/1 ui-monospace,Menlo,monospace;cursor:pointer}
.cti-rsi-bands-step button:hover{background:#18233A;color:#E4EBF7}
.cti-rsi-bands-n{min-width:20px;text-align:center;color:#F5B942;font-weight:700;font-size:10px}
.cti-rsi-bands-seg{display:inline-flex;margin-left:auto;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-rsi-bands-seg button{padding:1px 6px;border:0;background:#111826;color:#7C8AA5;font:600 8.5px/14px ui-monospace,Menlo,monospace;cursor:pointer}
.cti-rsi-bands-seg button+button{border-left:1px solid #22304A}
.cti-rsi-bands-seg button[aria-pressed="true"]{background:#1B2A45;color:#E4EBF7}
.cti-rsi-bands button:focus-visible{outline:2px solid #6EA8FF;outline-offset:-2px}
.cti-rsi-bands-plot{position:relative;border-radius:5px;background:#0A0D14;cursor:crosshair;outline:none}
.cti-rsi-bands-plot:focus-visible{box-shadow:0 0 0 1px #6EA8FF}
.cti-rsi-bands-svg{display:block;width:100%;height:152px;overflow:visible}
.cti-rsi-bands-gl{stroke:#1A2230;stroke-width:1}
.cti-rsi-bands-lv{stroke:#3A475F;stroke-width:1;stroke-dasharray:3 3}
.cti-rsi-bands-mid{stroke:#232D40;stroke-width:1}
.cti-rsi-bands-obz{fill:rgba(255,92,108,.06)}
.cti-rsi-bands-osz{fill:rgba(37,224,122,.06)}
.cti-rsi-bands-obf{fill:rgba(255,92,108,.42)}
.cti-rsi-bands-osf{fill:rgba(37,224,122,.42)}
.cti-rsi-bands-rl{fill:none;stroke:#B48CFF;stroke-width:1.3;stroke-linejoin:round}
.cti-rsi-bands-pl{fill:none;stroke:#C9D3E6;stroke-width:1.2;stroke-linejoin:round}
.cti-rsi-bands-pa{fill:rgba(110,168,255,.07)}
.cti-rsi-bands-ax{fill:#5B6883;font:8px ui-monospace,Menlo,monospace}
.cti-rsi-bands-pn{fill:#4B5772;font:7.5px ui-monospace,Menlo,monospace;letter-spacing:.08em;paint-order:stroke;stroke:#0A0D14;stroke-width:3px;stroke-linejoin:round}
.cti-rsi-bands-tag{fill:#1B2A45}
.cti-rsi-bands-tagr{fill:#3A2A5C}
.cti-rsi-bands-tagt{fill:#E4EBF7;font:700 8px ui-monospace,Menlo,monospace}
.cti-rsi-bands-mb{fill:#25E07A}
.cti-rsi-bands-ms{fill:#FF5C6C}
.cti-rsi-bands-tk{stroke-width:1;stroke-dasharray:1 2}
.cti-rsi-bands-tkb{stroke:#25E07A}
.cti-rsi-bands-tks{stroke:#FF5C6C}
.cti-rsi-bands-cur{stroke:#6EA8FF;stroke-width:1;opacity:.55}
.cti-rsi-bands-dot{fill:#0B0F17;stroke:#6EA8FF;stroke-width:1.4}
.cti-rsi-bands-rd{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin:6px 0 0;background:#182131;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-rsi-bands-rd div{background:#0E1420;padding:3px 5px;min-width:0}
.cti-rsi-bands-rd dt{font-size:7px;letter-spacing:.1em;color:#4B5772}
.cti-rsi-bands-rd dd{margin:0;font-size:9.5px;color:#D5DDEC;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cti-rsi-bands-up{color:#25E07A!important}
.cti-rsi-bands-dn{color:#FF5C6C!important}
.cti-rsi-bands-nt{color:#93A2BC!important}
.cti-rsi-bands-ft{display:flex;justify-content:space-between;gap:8px;margin-top:5px;font-size:8px;color:#5B6883;white-space:nowrap;overflow:hidden}
.cti-rsi-bands-ft span{overflow:hidden;text-overflow:ellipsis}
.cti-rsi-bands-ft b{font-weight:600;color:#C9D3E6}
@media (prefers-reduced-motion: reduce){.cti-rsi-bands *{transition:none!important;animation:none!important}}

