function SMA(a,n){var o=[],i,j,s,ok;for(i=0;i<a.length;i++){if(i<n-1){o.push(null);continue;}s=0;ok=true;for(j=i-n+1;j<=i;j++){if(a[j]==null){ok=false;break;}s+=a[j];}o.push(ok?s/n:null);}return o;}
function EMA(a,n,k){k=k||2/(n+1);var o=[],s=0,c=0,p=null,i,v;for(i=0;i<a.length;i++){v=a[i];if(v==null){o.push(null);continue;}if(p==null){s+=v;c++;if(c===n)p=s/n;o.push(p);}else{p=v*k+p*(1-k);o.push(p);}}return o;}
function DATES(n){var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],o=[],t=Date.UTC(2026,8,23),d,w;while(o.length<n){d=new Date(t);w=d.getUTCDay();if(w>0&&w<6)o.push((d.getUTCDate()<10?'0':'')+d.getUTCDate()+' '+M[d.getUTCMonth()]+' '+String(d.getUTCFullYear()).slice(2));t-=864e5;}return o.reverse();}
function SGN(v,d){var a=Math.abs(v).toFixed(d);return (+a===0?'':v>0?'+':'−')+a;}
function WID(el){var w=el.getBoundingClientRect().width;return w>60?Math.round(w):320;}
var C=[146.15,142.22,143.27,142.69,146.21,145.42,145.35,143.28,142.55,137.87,140.19,142.52,138.81,143.12,141.25,140.62,139.23,141.13,138.91,138.74,140.24,140.97,142.44,137.59,137.34,134.92,133.27,135.26,136.47,137.13,139.6,137.77,141.4,140.74,143.98,144.65,143.35,143.34,145.43,148.79,151.35,152.96,155.68,152.2,155.51,159.3,161.0,165.81,164.94,165.42,168.83,173.22,173.23,173.56,178.85,181.56,180.0,172.28,161.76,161.05,157.04,162.69,156.22,159.44,157.94,148.75,153.24,155.99,160.41,164.97,169.43,168.79,166.25,169.8,164.12,164.11,169.24,168.37,167.61,169.71,173.11,175.7,181.85,185.15,189.06,185.53,184.44,183.37,182.68,181.27,180.53,178.0,180.85,181.32,178.02,177.5,175.47,175.22,174.71,174.05,181.67,185.29,186.41,184.42,185.6,182.51,184.62,186.48,186.2,189.75,190.02,176.2,169.85,164.27,157.53,159.11,157.33,156.44,148.46,146.72,148.31,151.75,153.51,156.84,159.11,162.42,161.03,165.14,169.88,172.45];
var P='cti-rsi-bands-',N=C.length,V=90,S0=N-V,n=14,OB=70,OS=30,cur=N-1,W=320,H=152,RA=30,R,lo,hi,cl,dp,dr;
var D=DATES(N),svg=root.querySelector('.'+P+'svg'),plot=root.querySelector('.'+P+'plot');
var uid=P+Math.random().toString(36).slice(2,8);
function q(s){return root.querySelector('.'+P+s);}
function calc(){
  var r=[],ag=[],al=[],g=0,l=0,i,d,sig=[];
  for(i=0;i<N;i++){r.push(null);ag.push(null);al.push(null);}
  for(i=1;i<=n;i++){d=C[i]-C[i-1];if(d>0)g+=d;else l-=d;}
  g/=n;l/=n;ag[n]=g;al[n]=l;r[n]=l?100-100/(1+g/l):100;
  for(i=n+1;i<N;i++){d=C[i]-C[i-1];g=(g*(n-1)+(d>0?d:0))/n;l=(l*(n-1)+(d<0?-d:0))/n;ag[i]=g;al[i]=l;r[i]=l?100-100/(1+g/l):100;}
  for(i=S0+1;i<N;i++){
    if(r[i-1]>=OB&&r[i]<OB)sig.push({i:i,t:'S'});
    else if(r[i-1]<=OS&&r[i]>OS)sig.push({i:i,t:'B'});
  }
  R={r:r,ag:ag,al:al,sig:sig};
}
function X(i){return 3+(i-S0)*(W-RA-6)/(V-1);}
function Yp(v){return 7+(hi-v)/(hi-lo)*48;}
function Yr(v){return 146-v*0.8;}
function f1(v){return v.toFixed(1);}
function draw(){
  W=WID(svg);svg.setAttribute('viewBox','0 0 '+W+' '+H);
  var i,h='',r=R.r,pr=W-RA,x0=f1(X(S0)),x1=f1(X(N-1)),pl='',ra='';
  lo=Infinity;hi=-Infinity;
  for(i=S0;i<N;i++){if(C[i]<lo)lo=C[i];if(C[i]>hi)hi=C[i];}
  var pd=(hi-lo)*.1;lo-=pd;hi+=pd;
  h+='<rect class="'+P+'obz" x="0" y="'+Yr(100)+'" width="'+pr+'" height="'+f1(Yr(OB)-Yr(100))+'"/>';
  h+='<rect class="'+P+'osz" x="0" y="'+f1(Yr(OS))+'" width="'+pr+'" height="'+f1(Yr(0)-Yr(OS))+'"/>';
  h+='<line class="'+P+'gl" x1="0" x2="'+W+'" y1="61.5" y2="61.5"/><line class="'+P+'gl" x1="'+(pr+.5)+'" x2="'+(pr+.5)+'" y1="0" y2="'+H+'"/>';
  h+='<text class="'+P+'pn" x="4" y="10">PX</text><text class="'+P+'pn" x="4" y="75">RSI('+n+')</text>';
  [OB,50,OS].forEach(function(v){h+='<line class="'+P+(v===50?'mid':'lv')+'" x1="0" x2="'+pr+'" y1="'+f1(Yr(v))+'" y2="'+f1(Yr(v))+'"/>';});
  for(i=S0;i<N;i++)pl+=(i===S0?'M':'L')+f1(X(i))+','+f1(Yp(C[i]));
  h+='<path class="'+P+'pa" d="'+pl+'L'+x1+',58L'+x0+',58Z"/><path class="'+P+'pl" d="'+pl+'"/>';
  var st=-1;
  for(i=S0;i<N;i++){if(r[i]==null)continue;if(st<0)st=i;ra+=(i===st?'M':'L')+f1(X(i))+','+f1(Yr(r[i]));}
  var xs=f1(X(st)),yo=f1(Yr(OB)),yu=f1(Yr(OS));
  h+='<clipPath id="'+uid+'a"><rect x="0" y="0" width="'+W+'" height="'+yo+'"/></clipPath><clipPath id="'+uid+'b"><rect x="0" y="'+yu+'" width="'+W+'" height="'+f1(H-Yr(OS))+'"/></clipPath>';
  h+='<path class="'+P+'obf" clip-path="url(#'+uid+'a)" d="'+ra+'L'+x1+','+yo+'L'+xs+','+yo+'Z"/>';
  h+='<path class="'+P+'osf" clip-path="url(#'+uid+'b)" d="'+ra+'L'+x1+','+yu+'L'+xs+','+yu+'Z"/>';
  h+='<path class="'+P+'rl" d="'+ra+'"/>';
  R.sig.forEach(function(s){
    var x=f1(X(s.i)),y=Yp(C[s.i]);
    h+='<line class="'+P+'tk '+P+(s.t==='B'?'tkb':'tks')+'" x1="'+x+'" x2="'+x+'" y1="'+f1(Yr(100))+'" y2="'+f1(Yr(0))+'"/>';
    h+=s.t==='B'?'<path class="'+P+'mb" d="M'+x+','+f1(y+3)+'l3.5,6h-7z"/>':'<path class="'+P+'ms" d="M'+x+','+f1(y-3)+'l3.5,-6h-7z"/>';
  });
  var yl=Yp(C[N-1]),yr=Yr(r[N-1]);
  [OB,50,OS].forEach(function(v){if(Math.abs(Yr(v)-yr)>=10)h+='<text class="'+P+'ax" x="'+(pr+4)+'" y="'+f1(Yr(v)+3)+'">'+v+'</text>';});
  h+='<rect class="'+P+'tag" x="'+(pr+1)+'" y="'+f1(yl-5.5)+'" width="'+(RA-1)+'" height="11" rx="2"/><text class="'+P+'tagt" x="'+(pr+3)+'" y="'+f1(yl+3)+'">'+C[N-1].toFixed(C[N-1]>=1000?0:1)+'</text>';
  h+='<rect class="'+P+'tagr" x="'+(pr+1)+'" y="'+f1(yr-5.5)+'" width="'+(RA-1)+'" height="11" rx="2"/><text class="'+P+'tagt" x="'+(pr+3)+'" y="'+f1(yr+3)+'">'+r[N-1].toFixed(1)+'</text>';
  h+='<line class="'+P+'cur" x1="0" x2="0" y1="0" y2="'+H+'"/><circle class="'+P+'dot" r="2.4" cx="0" cy="0"/><circle class="'+P+'dot" r="2.4" cx="0" cy="0"/>';
  svg.innerHTML=h;
  cl=svg.querySelector('.'+P+'cur');var ds=svg.querySelectorAll('.'+P+'dot');dp=ds[0];dr=ds[1];
  foot();move(cur);
}
function tone(el,c){el.classList.remove(P+'up',P+'dn',P+'nt');if(c)el.classList.add(P+c);}
function move(i){
  cur=Math.max(S0,Math.min(N-1,i));
  var x=f1(X(cur)),r=R.r[cur],ag=R.ag[cur],al=R.al[cur],ch=C[cur]-C[cur-1],e;
  cl.setAttribute('x1',x);cl.setAttribute('x2',x);
  dp.setAttribute('cx',x);dp.setAttribute('cy',f1(Yp(C[cur])));
  dr.setAttribute('cx',x);dr.setAttribute('cy',f1(Yr(r)));
  q('d0').textContent=D[cur];
  q('d1').textContent=C[cur].toFixed(2);
  e=q('d2');e.textContent=SGN(ch,2)+(ch>0?' ▲':ch<0?' ▼':'');tone(e,ch>0?'up':ch<0?'dn':'nt');
  e=q('d3');
  if(r>=OB){e.textContent='OVERBOUGHT';tone(e,'dn');}else if(r<=OS){e.textContent='OVERSOLD';tone(e,'up');}else{e.textContent='NEUTRAL';tone(e,'nt');}
  q('d4').textContent=ag.toFixed(3);
  q('d5').textContent=al.toFixed(3);
  q('d6').textContent=al?(ag/al).toFixed(3):'∞';
  e=q('d7');e.textContent=r.toFixed(2);tone(e,r>=OB?'dn':r<=OS?'up':'');
}
function foot(){
  var ob=0,os=0,i,r=R.r,s=R.sig[R.sig.length-1],b=0,x=0;
  for(i=S0;i<N;i++){if(r[i]>=OB)ob++;else if(r[i]<=OS)os++;}
  R.sig.forEach(function(z){if(z.t==='B')b++;else x++;});
  q('f0').innerHTML='&ge;'+OB+' <b>'+ob+'d</b> &middot; &le;'+OS+' <b>'+os+'d</b> &middot; sig <b>'+b+'B/'+x+'S</b>';
  if(s){var ret=(C[N-1]/C[s.i]-1)*100;q('f1').innerHTML='last <b>'+(s.t==='B'?'BUY ▲ exit OS':'SELL ▼ exit OB')+'</b> '+D[s.i].slice(0,6)+' @'+C[s.i].toFixed(2)+' <b class="'+P+(ret>=0?'up':'dn')+'">'+SGN(ret,1)+'%</b>';}
  else q('f1').textContent='no exit signal in '+V+' bars';
}
function step(d){n=Math.max(2,Math.min(30,n+d));q('n').textContent=n;calc();draw();}
root.querySelectorAll('.'+P+'step button').forEach(function(b){b.addEventListener('click',function(){step(+b.getAttribute('data-a'));});});
var segs=root.querySelectorAll('.'+P+'seg button');
segs.forEach(function(b){b.addEventListener('click',function(){OB=+b.getAttribute('data-lv');OS=100-OB;segs.forEach(function(o){o.setAttribute('aria-pressed',o===b?'true':'false');});calc();draw();});});
plot.addEventListener('pointermove',function(e){var b=svg.getBoundingClientRect();if(!b.width)return;var x=(e.clientX-b.left)*W/b.width;move(Math.round(S0+(x-3)*(V-1)/(W-RA-6)));});
plot.addEventListener('keydown',function(e){var k=e.key,s=e.shiftKey?5:1;
  if(k==='ArrowLeft')move(cur-s);else if(k==='ArrowRight')move(cur+s);else if(k==='Home')move(S0);else if(k==='End')move(N-1);
  else if(k==='+'||k==='=')step(1);else if(k==='-'||k==='_')step(-1);else return;e.preventDefault();});
var lc=C[N-1],pc=C[N-2],hc=q('chg');
q('last').textContent=lc.toFixed(2);
hc.textContent=SGN(lc-pc,2)+' '+SGN((lc/pc-1)*100,2)+'%';tone(hc,lc>=pc?'up':'dn');
calc();draw();
if(window.ResizeObserver){var lw=W,ro=new ResizeObserver(function(){if(!root.isConnected){ro.disconnect();return;}var w=WID(svg);if(w!==lw){lw=w;draw();}});ro.observe(svg);}

