.cti-macd-hist-tagm{fill:#1C3358}
.cti-macd-hist-tagt{fill:#E4EBF7;font:700 8px ui-monospace,Menlo,monospace}
.cti-macd-hist-cur{stroke:#6EA8FF;stroke-width:1;opacity:.55}
.cti-macd-hist-dot{fill:#0B0F17;stroke:#6EA8FF;stroke-width:1.4}
.cti-macd-hist-rd{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin:6px 0 0;background:#182131;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-macd-hist-rd div{background:#0E1420;padding:3px 5px;min-width:0}
.cti-macd-hist-rd dt{font-size:7px;letter-spacing:.1em;color:#4B5772}
.cti-macd-hist-rd dd{margin:0;font-size:9.5px;color:#D5DDEC;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cti-macd-hist-up{color:#25E07A!important}
.cti-macd-hist-dn{color:#FF5C6C!important}
.cti-macd-hist-nt{color:#93A2BC!important}
.cti-macd-hist-log{margin-top:6px;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-macd-hist-lh,.cti-macd-hist-row{display:grid;grid-template-columns:1.25fr 1fr 1fr .9fr 1fr;gap:4px;padding:2px 6px}
.cti-macd-hist-lh{font-size:7px;letter-spacing:.1em;color:#4B5772;background:#0E1420;border-bottom:1px solid #182131}
.cti-macd-hist-lh span:nth-child(n+3){text-align:right}
.cti-macd-hist-lr{max-height:66px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#22304A transparent}
.cti-macd-hist-row{width:100%;border:0;background:transparent;color:#C9D3E6;font:9px/1.45 ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;text-align:left;cursor:pointer}
.cti-macd-hist-row:nth-child(even){background:#0D121C}
.cti-macd-hist-row:hover{background:#131C2C}
.cti-macd-hist-row[aria-current="true"]{background:#16233A;box-shadow:inset 2px 0 0 #6EA8FF}
.cti-macd-hist-row span:nth-child(n+3){text-align:right}
.cti-macd-hist-row em{font-style:normal;font-size:7px;color:#F5B942;margin-left:3px}
.cti-macd-hist-sum{display:flex;justify-content:space-between;padding:3px 6px;font-size:8px;color:#5B6883;background:#0E1420;border-top:1px solid #182131}
.cti-macd-hist-sum b{font-weight:600;color:#C9D3E6}
@media (prefers-reduced-motion: reduce){.cti-macd-hist *{transition:none!important;animation:none!important}}

