function SMA(a,n){var o=[],i,j,s,ok;for(i=0;i<a.length;i++){if(i<n-1){o.push(null);continue;}s=0;ok=true;for(j=i-n+1;j<=i;j++){if(a[j]==null){ok=false;break;}s+=a[j];}o.push(ok?s/n:null);}return o;}
function EMA(a,n,k){k=k||2/(n+1);var o=[],s=0,c=0,p=null,i,v;for(i=0;i<a.length;i++){v=a[i];if(v==null){o.push(null);continue;}if(p==null){s+=v;c++;if(c===n)p=s/n;o.push(p);}else{p=v*k+p*(1-k);o.push(p);}}return o;}
function DATES(n){var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],o=[],t=Date.UTC(2026,8,23),d,w;while(o.length<n){d=new Date(t);w=d.getUTCDay();if(w>0&&w<6)o.push((d.getUTCDate()<10?'0':'')+d.getUTCDate()+' '+M[d.getUTCMonth()]+' '+String(d.getUTCFullYear()).slice(2));t-=864e5;}return o.reverse();}
function SGN(v,d){var a=Math.abs(v).toFixed(d);return (+a===0?'':v>0?'+':'−')+a;}
function WID(el){var w=el.getBoundingClientRect().width;return w>60?Math.round(w):320;}
var C=[418.18,416.18,420.98,427.96,423.91,428.15,427.65,431.54,429.64,432.24,434.85,434.76,437.33,434.32,432.16,438.48,442.36,449.46,451.04,447.43,455.09,450.42,454.4,450.72,461.08,460.9,459.53,465.65,461.91,470.26,465.09,468.58,470.76,470.09,454.01,455.8,458.03,457.6,462.02,456.56,463.95,467.55,460.46,450.67,450.49,453.94,450.14,460.99,456.31,459.01,463.86,471.2,479.14,491.88,496.62,502.35,504.53,506.4,506.4,507.41,513.83,515.08,514.66,521.71,522.03,521.81,523.0,526.62,531.68,530.85,533.17,535.89,530.03,520.63,513.52,513.62,519.9,517.93,517.61,504.48,496.75,495.71,488.69,478.8,475.73,466.32,461.2,463.66,465.4,460.0,461.33,464.46,465.26,460.72,460.48,457.17,458.25,452.43,456.97,461.0,460.93,457.52,459.02,450.79,461.67,458.65,453.29,454.71,461.47,468.59,466.42,473.22,458.34,453.4,455.5,451.23,454.81,449.66,451.72,445.36,443.46,436.83,435.08,439.07,445.99,443.4,443.8,442.76,435.85,433.13,435.55,433.32,438.16,441.93,451.12,455.43,447.44,451.06,452.72,457.03,452.42,452.3,452.21,454.04,459.73,462.65,464.11,460.19,469.83,471.81];
var P='cti-macd-hist-',N=C.length,V=100,S0=N-V,pf=12,ps=26,pg=9,cur=N-1,W=320,H=160,RA=36,M,lo,hi,mlo,mhi,cl,dp,dm;
var D=DATES(N),svg=root.querySelector('.'+P+'svg'),plot=root.querySelector('.'+P+'plot'),list=root.querySelector('.'+P+'lr');
function q(s){return root.querySelector('.'+P+s);}
function f1(v){return v.toFixed(1);}
function tone(el,c){el.classList.remove(P+'up',P+'dn',P+'nt');if(c)el.classList.add(P+c);}
function calc(){
  var ef=EMA(C,pf),es=EMA(C,ps),m=[],h=[],x=[],i;
  for(i=0;i<N;i++)m.push(ef[i]!=null&&es[i]!=null?ef[i]-es[i]:null);
  var s=EMA(m,pg);
  for(i=0;i<N;i++)h.push(m[i]!=null&&s[i]!=null?m[i]-s[i]:null);
  for(i=S0+1;i<N;i++){
    if(h[i-1]==null||h[i]==null)continue;
    if(h[i-1]<=0&&h[i]>0)x.push({i:i,t:'B'});else if(h[i-1]>=0&&h[i]<0)x.push({i:i,t:'S'});
  }
  x.forEach(function(c,k){var e=k+1<x.length?x[k+1].i:N-1,r=(C[e]/C[c.i]-1)*100;c.e=e;c.open=k+1===x.length;c.pl=Math.round((c.t==='B'?r:-r)*100)/100;});
  M={ef:ef,es:es,m:m,s:s,h:h,x:x};
}
function X(i){return 3+(i-S0)*(W-RA-6)/(V-1);}
function Yp(v){return 6+(hi-v)/(hi-lo)*40;}
function Ym(v){return 62+(mhi-v)/(mhi-mlo)*92;}
function draw(){
  W=WID(svg);svg.setAttribute('viewBox','0 0 '+W+' '+H);
  var i,h='',pr=W-RA,pl='',ml='',sl='',st=-1,m=M.m,s=M.s,hs=M.h,v;
  lo=Infinity;hi=-Infinity;mlo=0;mhi=0;
  for(i=S0;i<N;i++){
    if(C[i]<lo)lo=C[i];if(C[i]>hi)hi=C[i];
    [m[i],s[i],hs[i]].forEach(function(z){if(z!=null){if(z<mlo)mlo=z;if(z>mhi)mhi=z;}});
  }
  v=(hi-lo)*.1;lo-=v;hi+=v;v=(mhi-mlo)*.08;mlo-=v;mhi+=v;
  h+='<line class="'+P+'gl" x1="0" x2="'+W+'" y1="54.5" y2="54.5"/><line class="'+P+'gl" x1="'+(pr+.5)+'" x2="'+(pr+.5)+'" y1="0" y2="'+H+'"/>';
  for(i=S0;i<N;i++)pl+=(i===S0?'M':'L')+f1(X(i))+','+f1(Yp(C[i]));
  h+='<path class="'+P+'pa" d="'+pl+'L'+f1(X(N-1))+',52L'+f1(X(S0))+',52Z"/><path class="'+P+'pl" d="'+pl+'"/>';
  var y0=Ym(0),bw=Math.max(1,(W-RA-6)/(V-1)*.64);
  h+='<line class="'+P+'zl" x1="0" x2="'+pr+'" y1="'+f1(y0)+'" y2="'+f1(y0)+'"/>';
  for(i=S0;i<N;i++){
    var hv=hs[i];if(hv==null)continue;
    var pv=hs[i-1]==null?hv:hs[i-1],cls=hv>=0?(hv>=pv?'hpu':'hpd'):(hv<=pv?'hnd':'hnu'),yy=Ym(hv);
    h+='<rect class="'+P+cls+'" x="'+f1(X(i)-bw/2)+'" y="'+f1(Math.min(yy,y0))+'" width="'+bw.toFixed(2)+'" height="'+Math.max(.6,Math.abs(yy-y0)).toFixed(1)+'"/>';
  }
  for(i=S0;i<N;i++){
    if(m[i]!=null)ml+=(ml?'L':'M')+f1(X(i))+','+f1(Ym(m[i]));
    if(s[i]!=null)sl+=(sl?'L':'M')+f1(X(i))+','+f1(Ym(s[i]));
  }
  h+='<path class="'+P+'sl" d="'+sl+'"/><path class="'+P+'ml" d="'+ml+'"/>';
  M.x.forEach(function(c){
    var x=f1(X(c.i)),y=Yp(C[c.i]);
    h+=c.t==='B'?'<path class="'+P+'mb" d="M'+x+','+f1(y+3)+'l3.5,6h-7z"/>':'<path class="'+P+'ms" d="M'+x+','+f1(y-3)+'l3.5,-6h-7z"/>';
    h+='<circle class="'+P+'xd '+P+(c.t==='B'?'xdb':'xds')+'" cx="'+x+'" cy="'+f1(Ym(m[c.i]))+'" r="2"/>';
  });
  h+='<text class="'+P+'pn" x="4" y="10">PX</text><text class="'+P+'pn" x="4" y="68"><tspan class="'+P+'km">MACD('+pf+','+ps+')</tspan> <tspan class="'+P+'ks">SIG('+pg+')</tspan> HIST</text>';
  var dec=Math.abs(mhi)>=10?1:2,ym=Ym(m[N-1]);
  [[mhi,Ym(mhi)+6],[mlo,Ym(mlo)-4],[0,y0]].forEach(function(z){if(Math.abs(z[1]-ym)>=10&&(z[0]===0?(y0-Ym(mhi)>16&&Ym(mlo)-y0>12):true))h+='<text class="'+P+'ax" x="'+(pr+4)+'" y="'+f1(z[1]+3)+'">'+(z[0]===0?'0':SGN(z[0],dec))+'</text>';});
  var yl=Yp(C[N-1]);
  h+='<rect class="'+P+'tag" x="'+(pr+1)+'" y="'+f1(yl-5.5)+'" width="'+(RA-1)+'" height="11" rx="2"/><text class="'+P+'tagt" x="'+(pr+3)+'" y="'+f1(yl+3)+'">'+C[N-1].toFixed(1)+'</text>';
  h+='<rect class="'+P+'tagm" x="'+(pr+1)+'" y="'+f1(ym-5.5)+'" width="'+(RA-1)+'" height="11" rx="2"/><text class="'+P+'tagt" x="'+(pr+3)+'" y="'+f1(ym+3)+'">'+SGN(m[N-1],2)+'</text>';
  h+='<line class="'+P+'cur" x1="0" x2="0" y1="0" y2="'+H+'"/><circle class="'+P+'dot" r="2.4" cx="0" cy="0"/><circle class="'+P+'dot" r="2.4" cx="0" cy="0"/>';
  svg.innerHTML=h;
  cl=svg.querySelector('.'+P+'cur');var ds=svg.querySelectorAll('.'+P+'dot');dp=ds[0];dm=ds[1];
  move(cur);
}
function logs(){
  var h='',hit=0,sum=0,cl0=0;
  M.x.slice().reverse().forEach(function(c){
    var up=c.pl>=0;if(!c.open){cl0++;if(c.pl>0)hit++;}sum+=c.pl;
    h+='<button type="button" role="listitem" class="'+P+'row" data-i="'+c.i+'" aria-current="false"><span>'+D[c.i]+'</span><span class="'+P+(c.t==='B'?'up':'dn')+'">'+(c.t==='B'?'▲ BULL':'▼ BEAR')+'</span><span>'+C[c.i].toFixed(2)+'</span><span>'+SGN(M.m[c.i],2)+'</span><span class="'+P+(up?'up':'dn')+'">'+SGN(c.pl,2)+'%'+(c.open?'<em>OPEN</em>':'')+'</span></button>';
  });
  list.innerHTML=h||'<div class="'+P+'row">no crosses in window</div>';
  sum=Math.round(sum*100)/100;
  q('sum').innerHTML='<span>'+M.x.length+' crosses &middot; hit <b>'+hit+'/'+cl0+'</b> closed</span><span>&Sigma; SIG P&amp;L <b class="'+P+(sum>=0?'up':'dn')+'">'+SGN(sum,2)+'%</b></span>';
  list.querySelectorAll('button').forEach(function(b){
    b.addEventListener('click',function(){move(+b.getAttribute('data-i'));});
    b.addEventListener('keydown',function(e){var t=null;if(e.key==='ArrowDown')t=b.nextElementSibling;else if(e.key==='ArrowUp')t=b.previousElementSibling;else if(e.key==='Enter'||e.key===' '){move(+b.getAttribute('data-i'));e.preventDefault();return;}if(t){t.focus();move(+t.getAttribute('data-i'));e.preventDefault();}});
  });
}
function move(i){
  cur=Math.max(S0,Math.min(N-1,i));
  var x=f1(X(cur)),m=M.m[cur],s=M.s[cur],hv=M.h[cur],pv=M.h[cur-1],e,ph;
  cl.setAttribute('x1',x);cl.setAttribute('x2',x);
  dp.setAttribute('cx',x);dp.setAttribute('cy',f1(Yp(C[cur])));
  dm.setAttribute('cx',x);dm.setAttribute('cy',f1(Ym(m)));
  q('d0').textContent=D[cur];
  q('d1').textContent=M.ef[cur].toFixed(2);
  q('d2').textContent=M.es[cur].toFixed(2);
  e=q('d3');e.textContent=SGN(m,3);tone(e,m>=0?'up':'dn');
  q('d4').textContent=C[cur].toFixed(2);
  q('d5').textContent=SGN(s,3);
  e=q('d6');e.textContent=SGN(hv,3);tone(e,hv>=0?'up':'dn');
  ph=hv>=0?(hv>=pv?'BULL ACC':'BULL FADE'):(hv<=pv?'BEAR ACC':'BEAR FADE');
  e=q('d7');e.textContent=ph;tone(e,hv>=0?(hv>=pv?'up':'nt'):(hv<=pv?'dn':'nt'));
  list.querySelectorAll('button').forEach(function(b){b.setAttribute('aria-current',+b.getAttribute('data-i')===cur?'true':'false');});
}
var segs=root.querySelectorAll('.'+P+'seg button');
segs.forEach(function(b){b.addEventListener('click',function(){
  var p=b.getAttribute('data-p').split(',');pf=+p[0];ps=+p[1];pg=+p[2];
  segs.forEach(function(o){o.setAttribute('aria-pressed',o===b?'true':'false');});
  q('l1').textContent='EMA '+pf;q('l2').textContent='EMA '+ps;q('l3').textContent='SIGNAL '+pg;
  calc();logs();draw();
});});
plot.addEventListener('pointermove',function(e){var b=svg.getBoundingClientRect();if(!b.width)return;var x=(e.clientX-b.left)*W/b.width;move(Math.round(S0+(x-3)*(V-1)/(W-RA-6)));});
plot.addEventListener('keydown',function(e){var k=e.key,s=e.shiftKey?5:1;
  if(k==='ArrowLeft')move(cur-s);else if(k==='ArrowRight')move(cur+s);else if(k==='Home')move(S0);else if(k==='End')move(N-1);else return;e.preventDefault();});
var lc=C[N-1],pc=C[N-2],hc=q('chg');
q('last').textContent=lc.toFixed(2);
hc.textContent=SGN(lc-pc,2)+' '+SGN((lc/pc-1)*100,2)+'%';tone(hc,lc>=pc?'up':'dn');
calc();logs();draw();
if(window.ResizeObserver){var lw=W,ro=new ResizeObserver(function(){if(!root.isConnected){ro.disconnect();return;}var w=WID(svg);if(w!==lw){lw=w;draw();}});ro.observe(svg);}

css:
.cti-boll-squeeze{box-sizing:border-box;width:100%;max-width:420px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 8px;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums}
.cti-boll-squeeze *{box-sizing:border-box}
.cti-boll-squeeze-hd{display:flex;align-items:baseline;gap:6px;margin-bottom:6px}
.cti-boll-squeeze-sym{font:700 11.5px/1 system-ui,-apple-system,"Segoe UI",sans-serif;color:#E4EBF7;letter-spacing:.02em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cti-boll-squeeze-sym b{font-weight:500;font-size:8.5px;color:#5B6883;letter-spacing:.04em}
.cti-boll-squeeze-tf{font-size:8px;color:#6EA8FF;border:1px solid #22304A;border-radius:3px;padding:0 4px;line-height:13px;flex-shrink:0}
