.cti-boll-squeeze-last{font-size:11px;color:#E4EBF7}
.cti-boll-squeeze-chg{font-style:normal}
.cti-boll-squeeze-par{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px;padding:4px 5px;margin-bottom:6px;background:#0E1420;border:1px solid #182131;border-radius:5px}
.cti-boll-squeeze-lb{font-size:8px;letter-spacing:.08em;color:#5B6883}
.cti-boll-squeeze-step{display:inline-flex;align-items:center;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-boll-squeeze-step button{width:16px;height:16px;padding:0;border:0;background:#111826;color:#93A2BC;font:700 10px/1 ui-monospace,Menlo,monospace;cursor:pointer}
.cti-boll-squeeze-step button:hover{background:#18233A;color:#E4EBF7}
.cti-boll-squeeze-n{min-width:20px;text-align:center;color:#F5B942;font-weight:700;font-size:10px}
.cti-boll-squeeze-seg{display:inline-flex;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-boll-squeeze-bb{margin-left:auto}
.cti-boll-squeeze-seg button{padding:1px 5px;border:0;background:#111826;color:#7C8AA5;font:600 8.5px/14px ui-monospace,Menlo,monospace;cursor:pointer}
.cti-boll-squeeze-seg button+button{border-left:1px solid #22304A}
.cti-boll-squeeze-seg button[aria-pressed="true"]{background:#1B2A45;color:#F5B942}
