.cti-boll-squeeze-band{fill:rgba(110,168,255,.08)}
.cti-boll-squeeze-ub,.cti-boll-squeeze-lob{fill:none;stroke:#6EA8FF;stroke-width:1.1;stroke-linejoin:round;opacity:.85}
.cti-boll-squeeze-mid{fill:none;stroke:#F5B942;stroke-width:1;stroke-dasharray:3 2;opacity:.85}
.cti-boll-squeeze-sqz{fill:rgba(245,185,66,.07)}
.cti-boll-squeeze-sqd{fill:#F5B942}
.cti-boll-squeeze-wk{stroke-width:1}
.cti-boll-squeeze-cu{fill:#25E07A;stroke:#25E07A}
.cti-boll-squeeze-cd{fill:#FF5C6C;stroke:#FF5C6C}
.cti-boll-squeeze-pb{fill:none;stroke:#C9D3E6;stroke-width:1.2;stroke-linejoin:round}
.cti-boll-squeeze-pbu{fill:rgba(37,224,122,.45)}
.cti-boll-squeeze-pbd{fill:rgba(255,92,108,.45)}
.cti-boll-squeeze-lv{stroke:#3A475F;stroke-width:1;stroke-dasharray:3 3}
.cti-boll-squeeze-ax{fill:#5B6883;font:8px ui-monospace,Menlo,monospace}
.cti-boll-squeeze-pn{fill:#4B5772;font:7.5px ui-monospace,Menlo,monospace;letter-spacing:.06em;paint-order:stroke;stroke:#0A0D14;stroke-width:3px;stroke-linejoin:round}
.cti-boll-squeeze-tag{fill:#1B2A45}
.cti-boll-squeeze-tagt{fill:#E4EBF7;font:700 8px ui-monospace,Menlo,monospace}
.cti-boll-squeeze-cur{stroke:#6EA8FF;stroke-width:1;opacity:.55}
.cti-boll-squeeze-dot{fill:#0B0F17;stroke:#6EA8FF;stroke-width:1.4}
.cti-boll-squeeze-st{display:flex;justify-content:space-between;gap:6px;margin-top:5px;font-size:8.5px;letter-spacing:.04em}
.cti-boll-squeeze-st span{padding:1px 6px;border-radius:3px;border:1px solid #22304A;background:#0E1420;color:#93A2BC;white-space:nowrap}
.cti-boll-squeeze-sq.cti-boll-squeeze-on{color:#F5B942;border-color:#5A4518;background:#1A1508}
.cti-boll-squeeze-sq.cti-boll-squeeze-on::before{content:"";display:inline-block;width:6px;height:6px;margin-right:4px;border-radius:50%;background:#F5B942;vertical-align:0;animation:cti-boll-squeeze-blink 1.2s steps(2,start) infinite}
@keyframes cti-boll-squeeze-blink{to{visibility:hidden}}
.cti-boll-squeeze-rd{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin:5px 0 0;background:#182131;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-boll-squeeze-rd div{background:#0E1420;padding:3px 5px;min-width:0}
.cti-boll-squeeze-rd dt{font-size:7px;letter-spacing:.08em;color:#4B5772;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cti-boll-squeeze-rd dd{margin:0;font-size:9.5px;color:#D5DDEC;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cti-boll-squeeze-up{color:#25E07A!important}
.cti-boll-squeeze-dn{color:#FF5C6C!important}
.cti-boll-squeeze-ft{display:flex;justify-content:space-between;gap:8px;margin-top:5px;font-size:8px;color:#5B6883;white-space:nowrap;overflow:hidden}
.cti-boll-squeeze-ft b{font-weight:600;color:#C9D3E6}
@media (prefers-reduced-motion: reduce){.cti-boll-squeeze *,.cti-boll-squeeze-sq.cti-boll-squeeze-on::before{transition:none!important;animation:none!important}}

.cti-gmma-ribbon{box-sizing:border-box;width:100%;max-width:420px;background:#0B0F17;border:1px solid #1C2432;border-radius:10px;padding:9px 9px 8px;font:9px/1.35 ui-monospace,Menlo,Consolas,monospace;color:#8B98B0;font-variant-numeric:tabular-nums}
.cti-gmma-ribbon *{box-sizing:border-box}
.cti-gmma-ribbon-hd{display:flex;align-items:baseline;gap:6px;margin-bottom:6px}
.cti-gmma-ribbon-sym{font:700 11.5px/1 system-ui,-apple-system,"Segoe UI",sans-serif;color:#E4EBF7;letter-spacing:.02em;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis}
.cti-gmma-ribbon-sym b{font-weight:500;font-size:8.5px;color:#5B6883;letter-spacing:.04em}
.cti-gmma-ribbon-tf{font-size:8px;color:#6EA8FF;border:1px solid #22304A;border-radius:3px;padding:0 4px;line-height:13px;flex-shrink:0}
.cti-gmma-ribbon-px{margin-left:auto;white-space:nowrap;flex-shrink:0}
.cti-gmma-ribbon-last{font-size:11px;color:#E4EBF7}
.cti-gmma-ribbon-chg{font-style:normal}
.cti-gmma-ribbon-par{display:flex;align-items:center;flex-wrap:wrap;gap:4px 5px;padding:4px 5px;margin-bottom:6px;background:#0E1420;border:1px solid #182131;border-radius:5px}
.cti-gmma-ribbon-lb{font-size:8px;letter-spacing:.08em;color:#5B6883}
.cti-gmma-ribbon-seg{display:inline-flex;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-gmma-ribbon-seg button{padding:1px 6px;border:0;background:#111826;color:#7C8AA5;font:600 8.5px/14px ui-monospace,Menlo,monospace;cursor:pointer}
.cti-gmma-ribbon-seg button+button{border-left:1px solid #22304A}
.cti-gmma-ribbon-seg button[aria-pressed="true"]{background:#1B2A45;color:#F5B942}
.cti-gmma-ribbon-tg{padding:1px 6px;border:1px solid #22304A;border-radius:4px;background:#111826;color:#5B6883;font:600 8px/14px ui-monospace,Menlo,monospace;letter-spacing:.04em;cursor:pointer}
.cti-gmma-ribbon-tgs{margin-left:auto}
.cti-gmma-ribbon-tgs[aria-pressed="true"]{color:#5FD4F4;border-color:#1E4A5C;background:#0C1C26}
.cti-gmma-ribbon-tgl[aria-pressed="true"]{color:#FF9A6B;border-color:#5C321E;background:#1F130C}
.cti-gmma-ribbon button:focus-visible{outline:2px solid #6EA8FF;outline-offset:-2px}
.cti-gmma-ribbon-plot{border-radius:5px;background:#0A0D14;cursor:crosshair;outline:none}
.cti-gmma-ribbon-plot:focus-visible{box-shadow:0 0 0 1px #6EA8FF}
.cti-gmma-ribbon-svg{display:block;width:100%;height:158px;overflow:visible}
.cti-gmma-ribbon-gl{stroke:#161D2A;stroke-width:1}
.cti-gmma-ribbon-ax{fill:#5B6883;font:8px ui-monospace,Menlo,monospace}
.cti-gmma-ribbon-axd{fill:#4B5772;font:7.5px ui-monospace,Menlo,monospace}
.cti-gmma-ribbon-fs{fill:rgba(79,195,247,.13)}
.cti-gmma-ribbon-fl{fill:rgba(255,138,92,.12)}
.cti-gmma-ribbon-m{fill:none;stroke-width:1;stroke-linejoin:round}
.cti-gmma-ribbon-s0{stroke:#B3ECFF}
.cti-gmma-ribbon-s1{stroke:#8FDDF8}
.cti-gmma-ribbon-s2{stroke:#6ECDF0}
.cti-gmma-ribbon-s3{stroke:#52BBE4}
.cti-gmma-ribbon-s4{stroke:#3AA7D4}
.cti-gmma-ribbon-s5{stroke:#2A92C2}
.cti-gmma-ribbon-l0{stroke:#FFC2A0}
.cti-gmma-ribbon-l1{stroke:#FFAA80}
.cti-gmma-ribbon-l2{stroke:#FF9466}
.cti-gmma-ribbon-l3{stroke:#F47E50}
.cti-gmma-ribbon-l4{stroke:#E26A3E}
.cti-gmma-ribbon-l5{stroke:#CC5630}
.cti-gmma-ribbon-cl{fill:none;stroke:#E4EBF7;stroke-width:1;stroke-linejoin:round;opacity:.9}
.cti-gmma-ribbon-rg1{fill:#25E07A}
.cti-gmma-ribbon-rg-1{fill:#FF5C6C}
.cti-gmma-ribbon-rg0{fill:#3A475F}
.cti-gmma-ribbon-pn{fill:#4B5772;font:7.5px ui-monospace,Menlo,monospace;letter-spacing:.06em;paint-order:stroke;stroke:#0A0D14;stroke-width:3px;stroke-linejoin:round}
.cti-gmma-ribbon-tag{fill:#1B2A45}
.cti-gmma-ribbon-tagt{fill:#E4EBF7;font:700 8px ui-monospace,Menlo,monospace}
.cti-gmma-ribbon-cur{stroke:#6EA8FF;stroke-width:1;opacity:.55}
.cti-gmma-ribbon-dot{fill:#0B0F17;stroke:#6EA8FF;stroke-width:1.4}
.cti-gmma-ribbon-st{display:flex;gap:4px;margin-top:5px;flex-wrap:wrap}
.cti-gmma-ribbon-st span{flex:1 1 auto;padding:1px 5px;border-radius:3px;border:1px solid #22304A;background:#0E1420;color:#93A2BC;font-size:8.5px;white-space:nowrap;text-align:center}
.cti-gmma-ribbon-tb{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:5px}
.cti-gmma-ribbon-col{border:1px solid #182131;border-radius:5px;overflow:hidden;min-width:0}
.cti-gmma-ribbon-th{display:flex;justify-content:space-between;padding:2px 5px;background:#0E1420;border-bottom:1px solid #182131;font-size:7px;letter-spacing:.1em;color:#4B5772}
.cti-gmma-ribbon-th em{font-style:normal;letter-spacing:.04em}
.cti-gmma-ribbon-r{display:grid;grid-template-columns:20px minmax(0,1fr) 34px 8px;gap:3px;padding:1px 5px;font-size:8px;line-height:1.5;color:#C9D3E6;white-space:nowrap}
.cti-gmma-ribbon-r:nth-child(even){background:#0D121C}
.cti-gmma-ribbon-r b{font-weight:600}
.cti-gmma-ribbon-r span{text-align:right}
.cti-gmma-ribbon-r i{font-style:normal;font-size:7px;text-align:center}
.cti-gmma-ribbon-rs0 .cti-gmma-ribbon-r b{color:#5FD4F4}
.cti-gmma-ribbon-rs1 .cti-gmma-ribbon-r b{color:#FF9A6B}
.cti-gmma-ribbon-up{color:#25E07A!important}
.cti-gmma-ribbon-dn{color:#FF5C6C!important}
.cti-gmma-ribbon-nt{color:#93A2BC!important}
.cti-gmma-ribbon-ft{display:flex;justify-content:space-between;gap:8px;margin-top:4px;font-size:7.5px;color:#4B5772;white-space:nowrap;overflow:hidden}
@media (prefers-reduced-motion: reduce){.cti-gmma-ribbon *{transition:none!important;animation:none!important}}

