var P='cti-gmma-ribbon-',N=C.length,V=100,S0=N-V,SP=[3,5,8,10,12,15],LP=[30,35,40,45,50,60],mode='E',showS=true,showL=true,cur=N-1,W=320,HT=158,RA=40,G,lo,hi,cl,dp;
var D=DATES(N),svg=root.querySelector('.'+P+'svg'),plot=root.querySelector('.'+P+'plot');
