  var i,h='',pr=W-RA,st=(W-RA-6)/(V-1),v;
  lo=Infinity;hi=-Infinity;
  for(i=S0;i<N;i++){lo=Math.min(lo,C[i]);hi=Math.max(hi,C[i]);G.s.concat(G.l).forEach(function(a){if(a[i]<lo)lo=a[i];if(a[i]>hi)hi=a[i];});}
