  if(showL){h+='<path class="'+P+'fl" d="'+band(G.l)+'"/>';G.l.forEach(function(a,k){h+='<path class="'+P+'m '+P+'l'+k+'" d="'+line(a)+'"/>';});}
  if(showS){h+='<path class="'+P+'fs" d="'+band(G.s)+'"/>';G.s.forEach(function(a,k){h+='<path class="'+P+'m '+P+'s'+k+'" d="'+line(a)+'"/>';});}
