  for(i=S0;i<N;i++)h+='<rect class="'+P+'rg'+G.reg[i]+'" x="'+f1(X(i)-st/2)+'" y="135" width="'+(st+.25).toFixed(2)+'" height="5"/>';
  h+='<text class="'+P+'pn" x="4" y="10">'+(mode==='E'?'EMA':'SMA')+' 3/5/8/10/12/15 &#183; 30/35/40/45/50/60</text>';
  h+='<text class="'+P+'axd" x="3" y="152">'+D[S0]+'</text><text class="'+P+'axd" x="'+f1(X(S0+50))+'" y="152" text-anchor="middle">'+D[S0+50]+'</text><text class="'+P+'axd" x="'+f1(pr-2)+'" y="152" text-anchor="end">'+D[N-1]+'</text>';
