.cti-stoch-cross-step{display:inline-flex;align-items:center;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-stoch-cross-step button{width:16px;height:16px;padding:0;border:0;background:#111826;color:#93A2BC;font:700 10px/1 ui-monospace,Menlo,monospace;cursor:pointer}
.cti-stoch-cross-step button:hover{background:#18233A;color:#E4EBF7}
.cti-stoch-cross-n{min-width:20px;text-align:center;color:#F5B942;font-weight:700;font-size:10px}
.cti-stoch-cross-seg{display:inline-flex;border:1px solid #22304A;border-radius:4px;overflow:hidden}
.cti-stoch-cross-seg button{min-width:17px;padding:1px 4px;border:0;background:#111826;color:#7C8AA5;font:600 8.5px/14px ui-monospace,Menlo,monospace;cursor:pointer}
.cti-stoch-cross-seg button+button{border-left:1px solid #22304A}
.cti-stoch-cross-seg button[aria-pressed="true"]{background:#1B2A45;color:#F5B942}
.cti-stoch-cross button:focus-visible{outline:2px solid #6EA8FF;outline-offset:-2px}
.cti-stoch-cross-nm{margin-left:auto;font-size:8px;color:#93A2BC;letter-spacing:.04em}
.cti-stoch-cross-plot{border-radius:5px;background:#0A0D14;cursor:crosshair;outline:none}
.cti-stoch-cross-plot:focus-visible{box-shadow:0 0 0 1px #6EA8FF}
.cti-stoch-cross-svg{display:block;width:100%;height:166px;overflow:visible}
.cti-stoch-cross-gl{stroke:#1A2230;stroke-width:1}
.cti-stoch-cross-bar{stroke-width:1}
.cti-stoch-cross-bu{stroke:#25E07A}
.cti-stoch-cross-bd{stroke:#FF5C6C}
.cti-stoch-cross-win{fill:rgba(110,168,255,.08);stroke:#6EA8FF;stroke-width:1;stroke-dasharray:2 2}
.cti-stoch-cross-wl{stroke:#6EA8FF;stroke-width:1;opacity:.8}
.cti-stoch-cross-wt{fill:#6EA8FF;font:700 7.5px ui-monospace,Menlo,monospace}
.cti-stoch-cross-obz{fill:rgba(255,92,108,.07)}
.cti-stoch-cross-osz{fill:rgba(37,224,122,.07)}
.cti-stoch-cross-lv{stroke:#3A475F;stroke-width:1;stroke-dasharray:3 3}
.cti-stoch-cross-mid{stroke:#1E2738;stroke-width:1}
.cti-stoch-cross-kl{fill:none;stroke:#5FD4F4;stroke-width:1.3;stroke-linejoin:round}
.cti-stoch-cross-dl{fill:none;stroke:#F5B942;stroke-width:1.1;stroke-dasharray:3 2;stroke-linejoin:round}
.cti-stoch-cross-xb{fill:#25E07A}
.cti-stoch-cross-xs{fill:#FF5C6C}
.cti-stoch-cross-xn{fill:#4B5772}
.cti-stoch-cross-ax{fill:#5B6883;font:8px ui-monospace,Menlo,monospace}
.cti-stoch-cross-pn{fill:#4B5772;font:7.5px ui-monospace,Menlo,monospace;letter-spacing:.06em;paint-order:stroke;stroke:#0A0D14;stroke-width:3px;stroke-linejoin:round}
.cti-stoch-cross-pn tspan.cti-stoch-cross-tk{fill:#5FD4F4}
.cti-stoch-cross-pn tspan.cti-stoch-cross-td{fill:#F5B942}
.cti-stoch-cross-tag{fill:#1B2A45}
.cti-stoch-cross-tagt{fill:#E4EBF7;font:700 8px ui-monospace,Menlo,monospace}
.cti-stoch-cross-cur{stroke:#6EA8FF;stroke-width:1;opacity:.5}
.cti-stoch-cross-dot{fill:#0B0F17;stroke:#5FD4F4;stroke-width:1.4}
.cti-stoch-cross-rd{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin:6px 0 0;background:#182131;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-stoch-cross-rd div{background:#0E1420;padding:3px 5px;min-width:0}
.cti-stoch-cross-rd dt{font-size:7px;letter-spacing:.1em;color:#4B5772}
.cti-stoch-cross-rd dd{margin:0;font-size:9.5px;color:#D5DDEC;text-align:right;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cti-stoch-cross-up{color:#25E07A!important}
.cti-stoch-cross-dn{color:#FF5C6C!important}
.cti-stoch-cross-nt{color:#93A2BC!important}
.cti-stoch-cross-log{margin-top:6px;border:1px solid #182131;border-radius:5px;overflow:hidden}
.cti-stoch-cross-lhd,.cti-stoch-cross-row{display:grid;grid-template-columns:1.2fr 1.5fr .7fr .7fr 1fr .9fr;gap:3px;padding:2px 6px}
.cti-stoch-cross-lhd{font-size:7px;letter-spacing:.08em;color:#4B5772;background:#0E1420;border-bottom:1px solid #182131}
.cti-stoch-cross-lhd span:nth-child(n+3){text-align:right}
.cti-stoch-cross-lr{max-height:56px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#22304A transparent}
.cti-stoch-cross-row{width:100%;border:0;background:transparent;color:#C9D3E6;font:8.5px/1.5 ui-monospace,Menlo,monospace;font-variant-numeric:tabular-nums;text-align:left;cursor:pointer;white-space:nowrap}
.cti-stoch-cross-row:nth-child(even){background:#0D121C}
.cti-stoch-cross-row:hover{background:#131C2C}
.cti-stoch-cross-row[aria-current="true"]{background:#16233A;box-shadow:inset 2px 0 0 #6EA8FF}
.cti-stoch-cross-row span:nth-child(n+3){text-align:right}
@media (prefers-reduced-motion: reduce){.cti-stoch-cross *{transition:none!important;animation:none!important}}

