function SMA(a,n){var o=[],i,j,s,ok;for(i=0;i<a.length;i++){if(i<n-1){o.push(null);continue;}s=0;ok=true;for(j=i-n+1;j<=i;j++){if(a[j]==null){ok=false;break;}s+=a[j];}o.push(ok?s/n:null);}return o;}
function EMA(a,n,k){k=k||2/(n+1);var o=[],s=0,c=0,p=null,i,v;for(i=0;i<a.length;i++){v=a[i];if(v==null){o.push(null);continue;}if(p==null){s+=v;c++;if(c===n)p=s/n;o.push(p);}else{p=v*k+p*(1-k);o.push(p);}}return o;}
function DATES(n){var M=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],o=[],t=Date.UTC(2026,8,23),d,w;while(o.length<n){d=new Date(t);w=d.getUTCDay();if(w>0&&w<6)o.push((d.getUTCDate()<10?'0':'')+d.getUTCDate()+' '+M[d.getUTCMonth()]+' '+String(d.getUTCFullYear()).slice(2));t-=864e5;}return o.reverse();}
function SGN(v,d){var a=Math.abs(v).toFixed(d);return (+a===0?'':v>0?'+':'−')+a;}
function WID(el){var w=el.getBoundingClientRect().width;return w>60?Math.round(w):320;}
