var P='cti-stoch-cross-',N=C.length,V=90,S0=N-V,n=14,ks=3,ds=3,cur=N-1,W=320,HT=166,RA=32,S,lo,hi,cl,dk;
var D=DATES(N),svg=root.querySelector('.'+P+'svg'),plot=root.querySelector('.'+P+'plot'),list=root.querySelector('.'+P+'lr'),win;
function q(s){return root.querySelector('.'+P+s);}
function f1(v){return v.toFixed(1);}
function tone(el,c){el.classList.remove(P+'up',P+'dn',P+'nt');if(c)el.classList.add(P+c);}
function calc(){
  var raw=[],hh=[],ll=[],i,j,a,b;
  for(i=0;i<N;i++){
    if(i<n-1){raw.push(null);hh.push(null);ll.push(null);continue;}
    a=-Infinity;b=Infinity;for(j=i-n+1;j<=i;j++){if(H[j]>a)a=H[j];if(L[j]<b)b=L[j];}
    hh.push(a);ll.push(b);raw.push(a>b?(C[i]-b)/(a-b)*100:50);
  }
  var k=SMA(raw,ks),d=SMA(k,ds),x=[];
  for(i=S0+1;i<N;i++){
    if(k[i-1]<=d[i-1]&&k[i]>d[i])x.push({i:i,t:'B',z:d[i]<20});
    else if(k[i-1]>=d[i-1]&&k[i]<d[i])x.push({i:i,t:'S',z:d[i]>80});
  }
  S={raw:raw,hh:hh,ll:ll,k:k,d:d,x:x};
}
function X(i){return 4+(i-S0)*(W-RA-8)/(V-1);}
function Yp(v){return 6+(hi-v)/(hi-lo)*64;}
function Yk(v){return 160-v*.74;}
function path(a){var s='',i;for(i=S0;i<N;i++)if(a[i]!=null)s+=(s?'L':'M')+f1(X(i))+','+f1(Yk(a[i]));return s;}
function draw(){
  W=WID(svg);svg.setAttribute('viewBox','0 0 '+W+' '+HT);
  var i,h='',pr=W-RA,tk=Math.max(1.5,(W-RA-8)/(V-1)*.45);
  lo=Infinity;hi=-Infinity;
  for(i=S0;i<N;i++){if(L[i]<lo)lo=L[i];if(H[i]>hi)hi=H[i];}
  var pd=(hi-lo)*.05;lo-=pd;hi+=pd;
  h+='<rect class="'+P+'obz" x="0" y="'+f1(Yk(100))+'" width="'+pr+'" height="'+f1(Yk(80)-Yk(100))+'"/><rect class="'+P+'osz" x="0" y="'+f1(Yk(20))+'" width="'+pr+'" height="'+f1(Yk(0)-Yk(20))+'"/>';
  h+='<line class="'+P+'gl" x1="0" x2="'+W+'" y1="76.5" y2="76.5"/><line class="'+P+'gl" x1="'+(pr+.5)+'" x2="'+(pr+.5)+'" y1="0" y2="'+HT+'"/>';
  h+='<line class="'+P+'mid" x1="0" x2="'+pr+'" y1="'+f1(Yk(50))+'" y2="'+f1(Yk(50))+'"/>';
  [80,20].forEach(function(v){h+='<line class="'+P+'lv" x1="0" x2="'+pr+'" y1="'+f1(Yk(v))+'" y2="'+f1(Yk(v))+'"/>';});
  [80,50,20].forEach(function(v){h+='<text class="'+P+'ax" x="'+(pr+4)+'" y="'+f1(Yk(v)+3)+'">'+v+'</text>';});
  h+='<rect class="'+P+'win" x="0" y="0" width="0" height="0"/><text class="'+P+'wt" x="0" y="0">HH</text><text class="'+P+'wt" x="0" y="0">LL</text>';
  for(i=S0;i<N;i++){
    var x=f1(X(i)),cls=P+'bar '+P+(C[i]>=C[i-1]?'bu':'bd');
    h+='<path class="'+cls+'" d="M'+x+','+f1(Yp(H[i]))+'V'+f1(Yp(L[i]))+'M'+x+','+f1(Yp(C[i]))+'h'+tk.toFixed(1)+'"/>';
  }
  h+='<path class="'+P+'dl" d="'+path(S.d)+'"/><path class="'+P+'kl" d="'+path(S.k)+'"/>';
  S.x.forEach(function(c){
    var x=X(c.i);
    if(!c.z)h+='<circle class="'+P+'xn" cx="'+f1(x)+'" cy="'+f1(Yk(S.k[c.i]))+'" r="1.4"/>';
    else if(c.t==='B')h+='<path class="'+P+'xb" d="M'+f1(x)+','+f1(Yk(S.k[c.i])+3)+'l3.2,5.5h-6.4z"/>';
    else h+='<path class="'+P+'xs" d="M'+f1(x)+','+f1(Yk(S.k[c.i])-3)+'l3.2,-5.5h-6.4z"/>';
  });
  h+='<text class="'+P+'pn" x="4" y="10">H-L-C</text><text class="'+P+'pn" x="4" y="87"><tspan class="'+P+'tk">%K</tspan> <tspan class="'+P+'td">%D</tspan> STO('+n+','+ks+','+ds+')</text>';
  var yc=Yp(C[N-1]);
  if(Math.abs(Yp(hi-pd)+3-yc)>=10)h+='<text class="'+P+'ax" x="'+(pr+4)+'" y="'+f1(Yp(hi-pd)+6)+'">'+(hi-pd).toFixed(0)+'</text>';
  if(Math.abs(Yp(lo+pd)-3-yc)>=10)h+='<text class="'+P+'ax" x="'+(pr+4)+'" y="'+f1(Yp(lo+pd))+'">'+(lo+pd).toFixed(0)+'</text>';
  h+='<rect class="'+P+'tag" x="'+(pr+1)+'" y="'+f1(yc-5.5)+'" width="'+(RA-1)+'" height="11" rx="2"/><text class="'+P+'tagt" x="'+(pr+3)+'" y="'+f1(yc+3)+'">'+C[N-1].toFixed(C[N-1]>=100?0:1)+'</text>';
  h+='<line class="'+P+'cur" x1="0" x2="0" y1="0" y2="'+HT+'"/><circle class="'+P+'dot" r="2.4" cx="0" cy="0"/>';
  svg.innerHTML=h;
  cl=svg.querySelector('.'+P+'cur');dk=svg.querySelector('.'+P+'dot');
  win={r:svg.querySelector('.'+P+'win'),t:svg.querySelectorAll('.'+P+'wt')};
  move(cur);
}
function logs(){
  var h='';
  S.x.filter(function(c){return c.z;}).reverse().forEach(function(c){
    var r=(C[N-1]/C[c.i]-1)*100,b=c.t==='B',pl=b?r:-r;
    h+='<button type="button" role="listitem" class="'+P+'row" data-i="'+c.i+'" aria-current="false"><span>'+D[c.i].slice(0,6)+'</span><span class="'+P+(b?'up':'dn')+'">'+(b?'▲ BULL OS':'▼ BEAR OB')+'</span><span>'+S.k[c.i].toFixed(1)+'</span><span>'+S.d[c.i].toFixed(1)+'</span><span>'+C[c.i].toFixed(2)+'</span><span class="'+P+(pl>=0?'up':'dn')+'">'+SGN(pl,1)+'%</span></button>';
  });
  list.innerHTML=h||'<div class="'+P+'row">no zone crosses in window</div>';
  list.querySelectorAll('button').forEach(function(b){
    b.addEventListener('click',function(){move(+b.getAttribute('data-i'));});
    b.addEventListener('keydown',function(e){var t=null;if(e.key==='ArrowDown')t=b.nextElementSibling;else if(e.key==='ArrowUp')t=b.previousElementSibling;if(t){t.focus();move(+t.getAttribute('data-i'));e.preventDefault();}});
  });
}
function move(i){
  cur=Math.max(S0,Math.min(N-1,i));
  var x=X(cur),e,k=S.k[cur],d=S.d[cur],a=S.hh[cur],b=S.ll[cur],x0=X(Math.max(S0,cur-n+1))-2,ya=Yp(a),yb=Yp(b);
  cl.setAttribute('x1',f1(x));cl.setAttribute('x2',f1(x));
  dk.setAttribute('cx',f1(x));dk.setAttribute('cy',f1(Yk(k)));
  win.r.setAttribute('x',f1(x0));win.r.setAttribute('y',f1(ya));win.r.setAttribute('width',f1(x-x0+2));win.r.setAttribute('height',f1(yb-ya));
  win.t[0].setAttribute('x',f1(x0+2));win.t[0].setAttribute('y',f1(ya-2));
  win.t[1].setAttribute('x',f1(x0+2));win.t[1].setAttribute('y',f1(yb+8));
  q('d0').textContent=D[cur];
  q('d1').textContent=a.toFixed(2);
  q('d2').textContent=b.toFixed(2);
  e=q('d3');e.textContent=C[cur].toFixed(2);tone(e,C[cur]>=C[cur-1]?'up':'dn');
  q('d4').textContent=S.raw[cur].toFixed(2);
  e=q('d5');e.textContent=k.toFixed(2);tone(e,k>=d?'up':'dn');
  q('d6').textContent=d.toFixed(2);
  e=q('d7');
  if(d>=80){e.textContent='OB ≥ 80';tone(e,'dn');}else if(d<=20){e.textContent='OS ≤ 20';tone(e,'up');}else{e.textContent=k>=d?'MID K>D':'MID K<D';tone(e,'nt');}
  list.querySelectorAll('button').forEach(function(bt){bt.setAttribute('aria-current',+bt.getAttribute('data-i')===cur?'true':'false');});
}
function labels(){q('n').textContent=n;q('lh').textContent='HH '+n;q('ll').textContent='LL '+n;q('nm').textContent=(ks===1?'FAST':ks===3?'SLOW':'FULL')+' STO('+n+','+ks+','+ds+')';}
function redo(){labels();calc();logs();draw();}
function step(v){n=Math.max(5,Math.min(21,n+v));redo();}
root.querySelectorAll('.'+P+'step button').forEach(function(b){b.addEventListener('click',function(){step(+b.getAttribute('data-a'));});});
function seg(sel,fn){var bs=root.querySelectorAll('.'+P+sel+' button');bs.forEach(function(b){b.addEventListener('click',function(){bs.forEach(function(o){o.setAttribute('aria-pressed',o===b?'true':'false');});fn(+b.getAttribute('data-v'));redo();});});}
seg('ks',function(v){ks=v;});
seg('ds',function(v){ds=v;});
plot.addEventListener('pointermove',function(e){var b=svg.getBoundingClientRect();if(!b.width)return;var x=(e.clientX-b.left)*W/b.width;move(Math.round(S0+(x-4)*(V-1)/(W-RA-8)));});
plot.addEventListener('keydown',function(e){var k=e.key,s=e.shiftKey?5:1;
  if(k==='ArrowLeft')move(cur-s);else if(k==='ArrowRight')move(cur+s);else if(k==='Home')move(S0);else if(k==='End')move(N-1);
  else if(k==='+'||k==='=')step(1);else if(k==='-'||k==='_')step(-1);else return;e.preventDefault();});
var lc=C[N-1],pc=C[N-2],hc=q('chg');
q('last').textContent=lc.toFixed(2);
hc.textContent=SGN(lc-pc,2)+' '+SGN((lc/pc-1)*100,2)+'%';tone(hc,lc>=pc?'up':'dn');
redo();
